/// Given a nonnegative i8 `a` (0 ≤ a ≤ 127), returns the number of octal digits
/// equal to 1 in its base-8 representation.
/// 
/// For example:
///   solve(0)   -> 0   // octal "0"
///   solve(1)   -> 1   // octal "1"
///   solve(8)   -> 1   // octal "10"
///   solve(9)   -> 2   // octal "11"
///   solve(73)  -> 1   // octal "111" has three '1's
pub fn solve(a: i8) -> i8 {
    // Work with an unsigned type for the loop so that `/` and `%`
    // behave as expected on nonnegative values.
    let mut v = a as u8;
    let mut count: i8 = 0;
    while v > 0 {
        if v % 8 == 1 {
            count += 1;
        }
        v /= 8;
    }
    count
}

